<script setup>
import { reactive, ref } from 'vue'; import MButton from '../../../components/mds/MButton.vue'; import MInput from '../../../components/mds/MInput.vue'; import MSelect from '../../../components/mds/MSelect.vue'; import MTextarea from '../../../components/mds/MTextarea.vue'; import { toInteractionCreateDraft, toInteractionCreatePayload } from '../domain/interaction-write.mjs';
const props = defineProps({ partner: { type: Object, default: null }, results: { type: Array, default: () => [] }, searching: { type: Boolean, default: false }, saving: { type: Boolean, default: false }, serverError: { type: String, default: '' } }); const emit = defineEmits(['cancel', 'search', 'select', 'save']); const draft = reactive(toInteractionCreateDraft()); const partnerQuery = ref(''); const localError = ref(''); const channels = ['', 'Gặp trực tiếp', 'Điện thoại', 'Email', 'Zalo', 'Khác'].map((value) => ({ value, label: value || 'Chọn kênh' })); const results = ['', 'Tốt', 'Đang theo dõi', 'Chưa đạt'].map((value) => ({ value, label: value || 'Chọn kết quả' }));
function find() { emit('search', partnerQuery.value.trim()); } function submit() { try { localError.value = ''; emit('save', toInteractionCreatePayload(draft, props.partner)); } catch (error) { localError.value = error.message; } }
</script>
<template><section class="min-h-0 bg-[var(--mds-bg-page)] p-4"><form class="mx-auto max-w-[880px] rounded-lg bg-[var(--mds-bg)] shadow-[var(--mds-shadow-card)]" novalidate @submit.prevent="submit"><header class="flex items-start justify-between gap-4 border-b border-[var(--mds-border-light)] px-5 py-4"><div><h1 class="text-[20px] font-semibold leading-7">Ghi nhận tương tác</h1><p class="mt-1 text-[13px] text-[var(--mds-text-secondary)]">Chọn đúng đối tác trước khi lưu; hệ thống tự gán người tạo ở máy chủ.</p></div><MButton variant="neutral" :disabled="saving" @click="emit('cancel')">Hủy</MButton></header><div class="grid gap-4 p-5 sm:grid-cols-2"><section class="sm:col-span-2"><span class="mb-1.5 block text-[13px] font-medium">Đối tác <span class="text-[var(--mds-danger)]">*</span></span><div class="flex gap-2"><MInput v-model="partnerQuery" placeholder="Tìm nhân sự hoặc cơ quan" :disabled="saving" @change="find" /><MButton variant="neutral" :loading="searching" @click="find">Tìm</MButton></div><div v-if="results.length" class="mt-2 divide-y divide-[var(--mds-border-light)] rounded-lg border border-[var(--mds-border-light)]"><MButton v-for="item in results" :key="`${item.type}-${item.id}`" variant="link" class="flex w-full justify-start px-3 py-2 text-left" @click="emit('select', item)"><span><strong>{{ item.name }}</strong><span class="ml-2 text-[12px] text-[var(--mds-text-secondary)]">{{ item.sub }}</span></span></MButton></div><p v-if="partner" class="mt-2 rounded-lg bg-[var(--mds-brand-50)] px-3 py-2 text-[13px] text-[var(--mds-brand-700)]">Đã chọn: <strong>{{ partner.name }}</strong> · {{ partner.type === 'person' ? 'Nhân sự' : 'Cơ quan' }}</p></section><label><span class="mb-1.5 block text-[13px] font-medium">Ngày <span class="text-[var(--mds-danger)]">*</span></span><MInput v-model="draft.date" type="date" :disabled="saving" /></label><label><span class="mb-1.5 block text-[13px] font-medium">Kênh</span><MSelect v-model="draft.channel" :options="channels" :disabled="saving" /></label><label><span class="mb-1.5 block text-[13px] font-medium">Kết quả</span><MSelect v-model="draft.result" :options="results" :disabled="saving" /></label><label><span class="mb-1.5 block text-[13px] font-medium">Người thực hiện</span><MInput v-model="draft.staff" :disabled="saving" /></label><label class="sm:col-span-2"><span class="mb-1.5 block text-[13px] font-medium">Nội dung</span><MTextarea v-model="draft.summary" placeholder="Ghi nhận nội dung trao đổi" :disabled="saving" /></label></div><p v-if="localError || serverError" role="alert" class="mx-5 mb-4 rounded-lg bg-[var(--mds-danger-bg)] px-3 py-2 text-[13px] text-[var(--mds-danger)]">{{ localError || serverError }}</p><footer class="sticky bottom-0 flex justify-end gap-2 border-t border-[var(--mds-border-light)] bg-[var(--mds-bg)] px-5 py-3"><MButton variant="neutral" :disabled="saving" @click="emit('cancel')">Hủy</MButton><MButton variant="primary" :loading="saving" :disabled="saving" @click="submit">Lưu tương tác</MButton></footer></form></section></template>
